    def click_button(self, bt: str):
        '''
        Click a button whose name should be in the keys of _buttons.
        '''
        _buttons = {"OK": SecurityObjects.security_window_OK_Button, "Cancel": SecurityObjects.security_window_Cancel_Button,"Drug Ordering": SecurityObjects.tiered_Security_Drug_Ordering_Button, "Drug Approval": SecurityObjects.tiered_Security_Drug_Approval_Button}
        if bt in _buttons:
            CommonActions.left_click_object(_buttons[bt])

    def select_tab(self, tab: str):
        '''
        Select a tab by click a location of tab's title, x of the relative coordinate is given as the value of the dict item

        where key is the name of the tab, and y is fixed to 10.
        '''
        tab_x = {"Admin":20, "Clinical":70, "UI Config":120, "Image":180, "Tiered Security":250, "MDD":320, "Orders":370}
        y = 10
        if tab in tab_x:
            #sq.mouseClick(sq.waitForObject(SecurityObjects.security_Pane), tab_x[tab], y, sq.MouseButton.PrimaryButton)
            CommonActions.mouse_click_with_relative_x_and_y_offsets(SecurityObjects.security_Pane, tab_x[tab], y)
